    int      ok;               /* GPU call + allocation plumbing succeeded */
    int      pass;              /* numeric comparison passed within tol */
    uint64_t n;
    uint64_t divergent_at;       /* index of first |ref-got| > tol, or n if none */
    float    max_abs_err;
    float    ref_at_divergence;
    float    got_at_divergence;
} kcmp_result;

